# apply_cat_reg_and_run.py — adds cat_smooth / cat_l2 / min_data_per_group to
# GBM ensemble, then runs an aggregated 3-prediction test to check stability.
import base64, pathlib, subprocess, sys

FILES = {
    'src/models/gbm_ranker.py': '',
}


def main():
    for target, b64 in FILES.items():
        p = pathlib.Path(target)
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(base64.b64decode(b64))
        print(f"wrote {target}")

    print("\nDefaults now:  cat_smooth=50, cat_l2=20, min_data_per_group=50")
    print("\nRun with tightened categorical:")
    print("  python -m src.cli.predict_next --no-refresh")
    print("\nCompare vs. no-driver:")
    print("  python -m src.cli.predict_next --no-refresh --drop-driver")

if __name__ == "__main__":
    main()
